#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    Closed,
    Truncated,
    LimitExceeded,
    TrailingData,
    Failed,
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Self::Closed => "closed",
            Self::Truncated => "truncated",
            Self::LimitExceeded => "limit exceeded",
            Self::TrailingData => "trailing data",
            Self::Failed => "failed",
        })
    }
}

impl std::error::Error for Error {}

#[derive(Default)]
pub struct Encoder {
    pending: Option<(u8, u8)>,
    closed: bool,
}

impl Encoder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn push(&mut self, input: &[u8]) -> Result<Vec<u8>, Error> {
        if self.closed {
            return Err(Error::Closed);
        }
        let mut output = Vec::new();
        for &byte in input {
            match self.pending {
                Some((count, value)) if value == byte => {
                    if count == 254 {
                        output.extend_from_slice(&[255, value]);
                        self.pending = None;
                    } else {
                        self.pending = Some((count + 1, value));
                    }
                }
                Some((count, value)) => {
                    output.extend_from_slice(&[count, value]);
                    self.pending = Some((1, byte));
                }
                None => self.pending = Some((1, byte)),
            }
        }
        Ok(output)
    }

    pub fn finish(&mut self) -> Result<Vec<u8>, Error> {
        if self.closed {
            return Ok(Vec::new());
        }
        self.closed = true;
        let mut output = Vec::new();
        if let Some((count, value)) = self.pending.take() {
            output.extend_from_slice(&[count, value]);
        }
        output.push(0);
        Ok(output)
    }
}

#[derive(Debug, PartialEq, Eq)]
pub struct Decoded {
    pub consumed: usize,
    pub bytes: Vec<u8>,
    pub ended: bool,
}

pub struct Decoder {
    max: usize,
    reserved: usize,
    count: Option<u8>,
    pending: Option<(u8, u8)>,
    ended: bool,
    failed: bool,
}

impl Decoder {
    pub fn new(max_decoded_bytes: usize) -> Self {
        Self {
            max: max_decoded_bytes,
            reserved: 0,
            count: None,
            pending: None,
            ended: false,
            failed: false,
        }
    }

    pub fn push(&mut self, input: &[u8], output_limit: usize) -> Result<Decoded, Error> {
        if self.failed {
            return Err(Error::Failed);
        }
        if self.ended {
            if !input.is_empty() {
                self.failed = true;
                return Err(Error::TrailingData);
            }
            return Ok(Decoded {
                consumed: 0,
                bytes: Vec::new(),
                ended: true,
            });
        }
        let mut consumed = 0;
        let mut bytes = Vec::new();
        while bytes.len() < output_limit {
            if let Some((remaining, value)) = self.pending.take() {
                let n = usize::from(remaining).min(output_limit - bytes.len());
                bytes.resize(bytes.len() + n, value);
                if n < usize::from(remaining) {
                    self.pending = Some((remaining - n as u8, value));
                }
                continue;
            }
            if consumed == input.len() {
                break;
            }
            if let Some(count) = self.count.take() {
                let value = input[consumed];
                consumed += 1;
                let count = usize::from(count);
                if count > self.max - self.reserved {
                    self.failed = true;
                    return Err(Error::LimitExceeded);
                }
                self.reserved += count;
                self.pending = Some((count as u8, value));
            } else {
                let count = input[consumed];
                consumed += 1;
                if count == 0 {
                    if consumed != input.len() {
                        self.failed = true;
                        return Err(Error::TrailingData);
                    }
                    self.ended = true;
                    break;
                }
                self.count = Some(count);
            }
        }
        Ok(Decoded {
            consumed,
            bytes,
            ended: self.ended,
        })
    }

    pub fn finish(&mut self) -> Result<(), Error> {
        if self.failed {
            return Err(Error::Failed);
        }
        if self.ended {
            return Ok(());
        }
        self.failed = true;
        Err(Error::Truncated)
    }
}

//! Streaming encoder and decoder for pebble-run streams.

use std::fmt;

/// A codec operation could not complete.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    /// The encoder has already finished.
    Closed,
    /// The decoder has not received a complete stream.
    Truncated,
    /// A run exceeds the cumulative decoded byte limit.
    LimitExceeded,
    /// Bytes follow the end marker.
    TrailingData,
    /// A previous decoder operation failed.
    Failed,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Closed => "encoder closed",
            Self::Truncated => "truncated stream",
            Self::LimitExceeded => "decoded limit exceeded",
            Self::TrailingData => "trailing data",
            Self::Failed => "decoder failed",
        })
    }
}

impl std::error::Error for Error {}

/// Incrementally produces canonical pebble-run streams.
#[derive(Default)]
pub struct Encoder {
    pending: Option<(u8, u8)>,
    closed: bool,
}

impl Encoder {
    /// Creates an empty encoder.
    pub fn new() -> Self {
        Self::default()
    }

    /// Encodes all input, retaining only an incomplete run.
    ///
    /// # Errors
    /// Returns [`Error::Closed`] after the encoder is finished.
    pub fn push(&mut self, input: &[u8]) -> Result<Vec<u8>, Error> {
        if self.closed {
            return Err(Error::Closed);
        }
        let mut output = Vec::new();
        for &value in input {
            match self.pending {
                Some((count, previous)) if previous == value => {
                    let count = count + 1;
                    if count == u8::MAX {
                        output.extend_from_slice(&[count, value]);
                        self.pending = None;
                    } else {
                        self.pending = Some((count, value));
                    }
                }
                Some((count, previous)) => {
                    output.extend_from_slice(&[count, previous]);
                    self.pending = Some((1, value));
                }
                None => self.pending = Some((1, value)),
            }
        }
        Ok(output)
    }

    /// Emits the final incomplete run and exactly one end marker.
    ///
    /// # Errors
    /// This operation does not return an error.
    pub fn finish(&mut self) -> Result<Vec<u8>, Error> {
        if self.closed {
            return Ok(Vec::new());
        }
        self.closed = true;
        let mut output = Vec::new();
        if let Some((count, value)) = self.pending.take() {
            output.extend_from_slice(&[count, value]);
        }
        output.push(0);
        Ok(output)
    }
}

/// A batch of decoded bytes and its input consumption.
#[derive(Debug, PartialEq, Eq)]
pub struct Decoded {
    /// Number of bytes consumed from the supplied input.
    pub consumed: usize,
    /// Expanded bytes produced by this call.
    pub bytes: Vec<u8>,
    /// Whether the end marker has been consumed.
    pub ended: bool,
}

enum State {
    Count,
    Value(u8),
    Run { remaining: u8, value: u8 },
    Ended,
    Failed,
}

/// Incrementally decodes a stream under a cumulative output cap.
pub struct Decoder {
    state: State,
    remaining_cap: usize,
}

impl Decoder {
    /// Creates a decoder whose complete runs may reserve at most this many bytes.
    pub fn new(max_decoded_bytes: usize) -> Self {
        Self { state: State::Count, remaining_cap: max_decoded_bytes }
    }

    /// Decodes at most `output_limit` bytes, leaving unconsumed input to the caller.
    ///
    /// # Errors
    /// Returns [`Error::LimitExceeded`] or [`Error::TrailingData`] on invalid input;
    /// any subsequent operation returns [`Error::Failed`].
    pub fn push(&mut self, input: &[u8], output_limit: usize) -> Result<Decoded, Error> {
        if matches!(self.state, State::Failed) {
            return Err(Error::Failed);
        }
        if matches!(self.state, State::Ended) {
            if !input.is_empty() {
                self.state = State::Failed;
                return Err(Error::TrailingData);
            }
            return Ok(Decoded { consumed: 0, bytes: Vec::new(), ended: true });
        }
        let mut consumed = 0;
        let mut bytes = Vec::new();
        while bytes.len() < output_limit {
            match self.state {
                State::Count => {
                    let Some(&count) = input.get(consumed) else { break };
                    consumed += 1;
                    if count == 0 {
                        if consumed != input.len() {
                            self.state = State::Failed;
                            return Err(Error::TrailingData);
                        }
                        self.state = State::Ended;
                        break;
                    }
                    self.state = State::Value(count);
                }
                State::Value(count) => {
                    let Some(&value) = input.get(consumed) else { break };
                    consumed += 1;
                    let count = usize::from(count);
                    if count > self.remaining_cap {
                        self.state = State::Failed;
                        return Err(Error::LimitExceeded);
                    }
                    self.remaining_cap -= count;
                    self.state = State::Run { remaining: count as u8, value };
                }
                State::Run { remaining, value } => {
                    let amount = usize::from(remaining).min(output_limit - bytes.len());
                    bytes.resize(bytes.len() + amount, value);
                    let left = usize::from(remaining) - amount;
                    self.state = if left == 0 { State::Count } else { State::Run { remaining: left as u8, value } };
                }
                State::Ended | State::Failed => break,
            }
        }
        Ok(Decoded { consumed, bytes, ended: matches!(self.state, State::Ended) })
    }

    /// Checks that the end marker has already been consumed.
    ///
    /// # Errors
    /// Returns [`Error::Truncated`] for an unfinished stream and [`Error::Failed`]
    /// after any previous error.
    pub fn finish(&mut self) -> Result<(), Error> {
        match self.state {
            State::Ended => Ok(()),
            State::Failed => Err(Error::Failed),
            _ => {
                self.state = State::Failed;
                Err(Error::Truncated)
            }
        }
    }
}

