use std::collections::HashSet;
use std::ffi::OsString;
use std::io::{self, Read, Write};

#[derive(Debug, PartialEq, Eq)]
enum Error {
    Usage,
    Input,
    Csv,
    Header,
    Width,
    Output,
}

impl Error {
    fn token(&self) -> &'static str {
        match self {
            Self::Usage => "E_USAGE",
            Self::Input => "E_INPUT",
            Self::Csv => "E_CSV",
            Self::Header => "E_HEADER",
            Self::Width => "E_WIDTH",
            Self::Output => "E_OUTPUT",
        }
    }
}

fn arguments(args: impl IntoIterator<Item = OsString>) -> Result<Vec<String>, Error> {
    let args: Vec<String> = args
        .into_iter()
        .map(|arg| arg.into_string().map_err(|_| Error::Usage))
        .collect::<Result<_, _>>()?;
    if args.is_empty() || args.iter().any(String::is_empty) {
        return Err(Error::Usage);
    }
    Ok(args)
}

#[derive(PartialEq, Eq)]
enum State {
    Start,
    Unquoted,
    Quoted,
    Closed,
}

fn parse(input: &str) -> Result<Vec<Vec<String>>, Error> {
    let bytes = input.as_bytes();
    let mut records = Vec::new();
    let mut record = Vec::new();
    let mut field = Vec::new();
    let mut state = State::Start;
    let mut pos = 0;
    let mut pending = false;
    while pos < bytes.len() {
        let byte = bytes[pos];
        if state == State::Quoted {
            if byte == b'"' {
                if bytes.get(pos + 1) == Some(&b'"') {
                    field.push(b'"');
                    pos += 1;
                } else {
                    state = State::Closed;
                }
            } else {
                field.push(byte);
            }
            pending = true;
        } else {
            match byte {
                b',' => {
                    record.push(String::from_utf8(field).map_err(|_| Error::Csv)?);
                    field = Vec::new();
                    state = State::Start;
                    pending = true;
                }
                b'\n' | b'\r' => {
                    if byte == b'\r' {
                        if bytes.get(pos + 1) != Some(&b'\n') {
                            return Err(Error::Csv);
                        }
                        pos += 1;
                    }
                    record.push(String::from_utf8(field).map_err(|_| Error::Csv)?);
                    field = Vec::new();
                    records.push(std::mem::take(&mut record));
                    state = State::Start;
                    pending = false;
                }
                b'"' if state == State::Start => {
                    state = State::Quoted;
                    pending = true;
                }
                _ if state == State::Closed || byte == b'"' => return Err(Error::Csv),
                _ => {
                    field.push(byte);
                    state = State::Unquoted;
                    pending = true;
                }
            }
        }
        pos += 1;
    }
    if state == State::Quoted {
        return Err(Error::Csv);
    }
    if pending {
        record.push(String::from_utf8(field).map_err(|_| Error::Csv)?);
        records.push(record);
    }
    Ok(records)
}

fn project(input: &[u8], selected: &[String]) -> Result<Vec<u8>, Error> {
    let text = std::str::from_utf8(input).map_err(|_| Error::Input)?;
    let records = parse(text)?;
    let header = records.first().ok_or(Error::Header)?;
    let mut seen = HashSet::new();
    if header
        .iter()
        .any(|name| name.is_empty() || !seen.insert(name))
    {
        return Err(Error::Header);
    }
    let indices: Vec<usize> = selected
        .iter()
        .map(|name| {
            header
                .iter()
                .position(|field| field == name)
                .ok_or(Error::Header)
        })
        .collect::<Result<_, _>>()?;
    if records
        .iter()
        .skip(1)
        .any(|record| record.len() != header.len())
    {
        return Err(Error::Width);
    }
    let mut output = Vec::new();
    for record in records {
        for (i, &index) in indices.iter().enumerate() {
            if i > 0 {
                output.push(b',');
            }
            output.push(b'"');
            for &byte in record[index].as_bytes() {
                if byte == b'"' {
                    output.push(b'"');
                }
                output.push(byte);
            }
            output.push(b'"');
        }
        output.push(b'\n');
    }
    Ok(output)
}

fn run(
    args: impl IntoIterator<Item = OsString>,
    mut input: impl Read,
    mut output: impl Write,
) -> Result<(), Error> {
    let selected = arguments(args)?;
    let mut bytes = Vec::new();
    input.read_to_end(&mut bytes).map_err(|_| Error::Input)?;
    let result = project(&bytes, &selected)?;
    output.write_all(&result).map_err(|_| Error::Output)?;
    output.flush().map_err(|_| Error::Output)
}

fn main() {
    if let Err(error) = run(
        std::env::args_os().skip(1),
        io::stdin().lock(),
        io::stdout().lock(),
    ) {
        eprintln!("{}: unable to project CSV", error.token());
        std::process::exit(if error == Error::Usage { 2 } else { 1 });
    }
}

use std::collections::HashMap;
use std::ffi::OsString;
use std::io::{self, Read, Write};

#[derive(Debug, PartialEq, Eq)]
enum Failure {
    Usage,
    Input,
    Csv,
    Header,
    Width,
    Output,
}

impl Failure {
    fn token(&self) -> &'static str {
        match self {
            Self::Usage => "E_USAGE",
            Self::Input => "E_INPUT",
            Self::Csv => "E_CSV",
            Self::Header => "E_HEADER",
            Self::Width => "E_WIDTH",
            Self::Output => "E_OUTPUT",
        }
    }
}

fn selections(args: impl IntoIterator<Item = OsString>) -> Result<Vec<String>, Failure> {
    let names: Vec<String> = args
        .into_iter()
        .map(|arg| arg.into_string().map_err(|_| Failure::Usage))
        .collect::<Result<_, _>>()?;
    if names.is_empty() || names.iter().any(String::is_empty) {
        return Err(Failure::Usage);
    }
    Ok(names)
}

fn parse_csv(input: &str) -> Result<Vec<Vec<String>>, Failure> {
    let mut chars = input.chars().peekable();
    let mut records = Vec::new();
    while chars.peek().is_some() {
        let mut record = Vec::new();
        loop {
            let mut field = String::new();
            if chars.peek() == Some(&'"') {
                chars.next();
                loop {
                    match chars.next() {
                        Some('"') if chars.peek() == Some(&'"') => {
                            chars.next();
                            field.push('"');
                        }
                        Some('"') => break,
                        Some(ch) => field.push(ch),
                        None => return Err(Failure::Csv),
                    }
                }
            } else {
                while let Some(&ch) = chars.peek() {
                    match ch {
                        ',' | '\r' | '\n' => break,
                        '"' => return Err(Failure::Csv),
                        _ => {
                            field.push(ch);
                            chars.next();
                        }
                    }
                }
            }
            record.push(field);
            match chars.next() {
                Some(',') => continue,
                Some('\n') | None => break,
                Some('\r') if chars.next() == Some('\n') => break,
                _ => return Err(Failure::Csv),
            }
        }
        records.push(record);
    }
    Ok(records)
}

fn project(input: &[u8], names: &[String]) -> Result<Vec<u8>, Failure> {
    let text = std::str::from_utf8(input).map_err(|_| Failure::Input)?;
    let records = parse_csv(text)?;
    let header = records.first().ok_or(Failure::Header)?;
    let mut indices = HashMap::new();
    for (index, name) in header.iter().enumerate() {
        if name.is_empty() || indices.insert(name.as_str(), index).is_some() {
            return Err(Failure::Header);
        }
    }
    let selected: Vec<usize> = names
        .iter()
        .map(|name| indices.get(name.as_str()).copied().ok_or(Failure::Header))
        .collect::<Result<_, _>>()?;
    if records.iter().skip(1).any(|row| row.len() != header.len()) {
        return Err(Failure::Width);
    }
    let mut output = Vec::new();
    for record in &records {
        for (position, &index) in selected.iter().enumerate() {
            if position != 0 {
                output.push(b',');
            }
            output.push(b'"');
            for ch in record[index].chars() {
                if ch == '"' {
                    output.push(b'"');
                }
                let mut encoded = [0; 4];
                output.extend_from_slice(ch.encode_utf8(&mut encoded).as_bytes());
            }
            output.push(b'"');
        }
        output.push(b'\n');
    }
    Ok(output)
}

fn run(
    args: impl IntoIterator<Item = OsString>,
    mut input: impl Read,
    mut output: impl Write,
) -> Result<(), Failure> {
    let names = selections(args)?;
    let mut bytes = Vec::new();
    input.read_to_end(&mut bytes).map_err(|_| Failure::Input)?;
    let result = project(&bytes, &names)?;
    output.write_all(&result).map_err(|_| Failure::Output)?;
    output.flush().map_err(|_| Failure::Output)
}

fn main() {
    if let Err(error) = run(
        std::env::args_os().skip(1),
        io::stdin().lock(),
        io::stdout().lock(),
    ) {
        eprintln!("{}", error.token());
        std::process::exit(if error == Failure::Usage { 2 } else { 1 });
    }
}

