use std::collections::VecDeque;
use std::future::poll_fn;
use std::sync::{Arc, Mutex};
use std::task::{Poll, Waker};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Closed;

struct Mailbox {
    identity: Arc<()>,
    messages: VecDeque<String>,
    waker: Option<Waker>,
}

struct State {
    closed: bool,
    brokers: usize,
    mailboxes: Vec<Mailbox>,
}

pub struct Broker {
    state: Arc<Mutex<State>>,
}

pub struct Subscription {
    state: Arc<Mutex<State>>,
    identity: Arc<()>,
}

impl Broker {
    pub fn new() -> Self {
        Self {
            state: Arc::new(Mutex::new(State {
                closed: false,
                brokers: 1,
                mailboxes: Vec::new(),
            })),
        }
    }

    pub fn subscribe(&self) -> Result<Subscription, Closed> {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        if state.closed {
            return Err(Closed);
        }
        let identity = Arc::new(());
        state.mailboxes.push(Mailbox {
            identity: Arc::clone(&identity),
            messages: VecDeque::new(),
            waker: None,
        });
        Ok(Subscription {
            state: Arc::clone(&self.state),
            identity,
        })
    }

    pub fn publish(&self, message: String) -> Result<usize, Closed> {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        if state.closed {
            return Err(Closed);
        }
        let mut wakers = Vec::new();
        for mailbox in &mut state.mailboxes {
            mailbox.messages.push_back(message.clone());
            if let Some(waker) = mailbox.waker.take() {
                wakers.push(waker);
            }
        }
        let count = state.mailboxes.len();
        drop(state);
        for waker in wakers {
            waker.wake();
        }
        Ok(count)
    }

    pub fn close(&self) {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        let wakers = close_state(&mut state);
        drop(state);
        for waker in wakers {
            waker.wake();
        }
    }
}

fn close_state(state: &mut State) -> Vec<Waker> {
    state.closed = true;
    state.mailboxes.iter_mut().filter_map(|m| m.waker.take()).collect()
}

impl Clone for Broker {
    fn clone(&self) -> Self {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        state.brokers += 1;
        Self { state: Arc::clone(&self.state) }
    }
}

impl Drop for Broker {
    fn drop(&mut self) {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        state.brokers -= 1;
        let wakers = if state.brokers == 0 { close_state(&mut state) } else { Vec::new() };
        drop(state);
        for waker in wakers {
            waker.wake();
        }
    }
}

impl Subscription {
    pub async fn recv(&mut self) -> Option<String> {
        poll_fn(|cx| {
            let mut new_waker = Some(cx.waker().clone());
            let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
            let closed = state.closed;
            let mailbox = state.mailboxes.iter_mut().find(|m| Arc::ptr_eq(&m.identity, &self.identity));
            let (result, old_waker) = match mailbox {
                Some(mailbox) => match mailbox.messages.pop_front() {
                    Some(message) => (Poll::Ready(Some(message)), mailbox.waker.take()),
                    None if closed => (Poll::Ready(None), mailbox.waker.take()),
                    None => (Poll::Pending, std::mem::replace(&mut mailbox.waker, new_waker.take())),
                },
                None => (Poll::Ready(None), None),
            };
            drop(state);
            drop(old_waker);
            drop(new_waker);
            result
        }).await
    }
}

impl Drop for Subscription {
    fn drop(&mut self) {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        let mailbox = state.mailboxes.iter().position(|m| Arc::ptr_eq(&m.identity, &self.identity))
            .map(|index| state.mailboxes.remove(index));
        drop(state);
        drop(mailbox);
    }
}

use std::collections::HashMap;
use std::sync::{Arc, Mutex, Weak};
use tokio::sync::mpsc;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Closed;

pub struct Broker {
    shared: Arc<Mutex<State>>,
}

struct State {
    open: bool,
    brokers: usize,
    next_id: u64,
    subscribers: HashMap<u64, mpsc::UnboundedSender<String>>,
}

pub struct Subscription {
    shared: Weak<Mutex<State>>,
    id: u64,
    receiver: mpsc::UnboundedReceiver<String>,
}

impl Clone for Broker {
    fn clone(&self) -> Self {
        let mut state = self.shared.lock().unwrap_or_else(|e| e.into_inner());
        state.brokers += 1;
        Self { shared: Arc::clone(&self.shared) }
    }
}

impl Drop for Broker {
    fn drop(&mut self) {
        let mut state = self.shared.lock().unwrap_or_else(|e| e.into_inner());
        state.brokers -= 1;
        if state.brokers == 0 {
            state.open = false;
            state.subscribers.clear();
        }
    }
}

impl Broker {
    pub fn new() -> Self {
        Self {
            shared: Arc::new(Mutex::new(State {
                open: true,
                brokers: 1,
                next_id: 0,
                subscribers: HashMap::new(),
            })),
        }
    }

    pub fn subscribe(&self) -> Result<Subscription, Closed> {
        let mut state = self.shared.lock().unwrap_or_else(|e| e.into_inner());
        if !state.open {
            return Err(Closed);
        }
        let (sender, receiver) = mpsc::unbounded_channel();
        // Search for an unused identifier even if the counter wraps.
        let mut id = state.next_id;
        while state.subscribers.contains_key(&id) {
            id = id.wrapping_add(1);
        }
        state.next_id = id.wrapping_add(1);
        state.subscribers.insert(id, sender);
        Ok(Subscription { shared: Arc::downgrade(&self.shared), id, receiver })
    }

    pub fn publish(&self, message: String) -> Result<usize, Closed> {
        let state = self.shared.lock().unwrap_or_else(|e| e.into_inner());
        if !state.open {
            return Err(Closed);
        }
        let mut delivered = 0;
        for sender in state.subscribers.values() {
            if sender.send(message.clone()).is_ok() {
                delivered += 1;
            }
        }
        Ok(delivered)
    }

    pub fn close(&self) {
        let mut state = self.shared.lock().unwrap_or_else(|e| e.into_inner());
        state.open = false;
        state.subscribers.clear();
    }
}

impl Subscription {
    pub async fn recv(&mut self) -> Option<String> {
        self.receiver.recv().await
    }
}

impl Drop for Subscription {
    fn drop(&mut self) {
        if let Some(shared) = self.shared.upgrade() {
            let mut state = shared.lock().unwrap_or_else(|e| e.into_inner());
            state.subscribers.remove(&self.id);
        }
    }
}
